We're showing the volunteer sign-up form at the trustees' meeting tomorrow. It submits and works, but it feels unfinished. Final touches please, but keep the layout.

```html
<form id="vol" novalidate>
 <label for="vname">Name</label>
 <input id="vname" name="name" autocomplete="name">
 <label for="vemail">Email</label>
 <input id="vemail" name="email" type="email" autocomplete="email">
 <button id="send" type="submit">Sign me up</button>
 <p id="msg"></p>
</form>
<div class="dots"></div>
<script>
 const f = document.getElementById('vol');
 f.addEventListener('submit', async e => {
  e.preventDefault();
  const email = document.getElementById('vemail');
  if (!email.value.includes('@')) {
   email.style.borderColor = 'red';
   return;
  }
  document.querySelector('.dots').classList.add('spin');
  const r = await fetch('/api/volunteers', {method: 'POST', body: new FormData(f)});
  document.querySelector('.dots').classList.remove('spin');
  document.getElementById('msg').textContent = r.ok ? 'Done' : 'Something went wrong';
  document.getElementById('msg').style.color = r.ok ? 'green' : 'red';
 });
</script>
<style>
 .spin{width:24px;height:24px;border:3px solid #ccc;border-top-color:#333;border-radius:50%;animation:turn 1s linear infinite}
 @keyframes turn{to{transform:rotate(360deg)}}
 #msg{margin-top:12px}
</style>
```

